"""The ``.net`` files the reader sweeps run over, split by whether git tracks them.

Three modules sweep "every ``.net`` file in the tree": ``test_net_reader_round_trip.py``,
``test_net_reader_review.py`` and ``test_primary_param_names.py``. Each carried
its own copy of one rglob over ``benchmarks/``, ``parity_checks/`` and ``tests/``,
and two of them documented it as finding the *committed* fixtures. It found
whatever was on disk. On a machine that has run the benchmark and parity suites,
that was 1675 gitignored files beside the 140 tracked ones (2026-10-11):

* 585 generated by the ``ode_fullnet`` benchmark (``benchmarks/suites/ode_fullnet/nets``);
* 660 written by bng_parity sweeps (``parity_checks/bng_parity/runs``), a set that
  grows every time a sweep runs;
* 414 inside the upstream repos bng_parity clones (``parity_checks/bng_parity/.sources_cache``);
* 16 benchmark inputs and results.

The copies had also drifted: one did not exclude ``.pytest_cache``.

The extra reach is worth keeping. It is how #266 went red on a developer's
pre-push hook while CI, which only ever has the tracked files, stayed green. The
problem was that it was accidental and unlabelled, so a failure on a
machine-local file looked like a failure on a committed fixture. This module
keeps the two sets apart:

* ``TRACKED``: what git tracks under those roots. The same on every machine,
  and the only set CI ever sees.
* ``LOCAL``: what is on disk under the same roots and not tracked. It differs
  from machine to machine and from run to run, and sweeps label these cases
  ``local:`` so a failure says which kind of file broke.

Without git (an sdist, or ``git`` not on PATH), the split cannot be made. Every
file on disk then counts as tracked, which is what the rglob used to assume
everywhere, and ``GIT`` is False.
"""

from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

import pytest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

from _source_root import bngsim_source_root  # noqa: E402

#: Resolved through the rig rather than ``__file__`` (issue #578): under
#: ``run_tests.sh`` this file runs from a temp-dir copy, whose parents are not the
#: repo.
ROOT = bngsim_source_root() or Path(__file__).resolve().parents[2]

#: Named rather than reached by rglob-ing the repo root (issue #590): a whole-tree
#: rglob sweeps up ``.venv`` and ``build`` trees, and ``Path.rglob`` does not
#: descend into a symlinked directory below the root of its walk.
ROOTS = ("benchmarks", "parity_checks", "tests")

#: Directories whose ``.net`` files are build or tool output, not models. Matched
#: against the path *below* ROOT. Matching the absolute path, as the copies did,
#: would drop every file in a checkout that lives under a directory named ``build``.
_EXCLUDED_DIRS = frozenset({"build", ".pytest_cache"})

#: The skip reason for a sweep with nothing to sweep. Worded to match the
#: declared "not present" in conftest's skip audit.
ABSENT = ".net files not present in this checkout"


def _rel(path: Path) -> str:
    return path.relative_to(ROOT).as_posix()


#: The variables that tell git WHICH repository to use. Only these are dropped.
#: The rest (GIT_CONFIG_GLOBAL, GIT_EXEC_PATH, GIT_SSH_*) are a caller's own
#: choices about how git behaves, and stripping them would undo, say, a
#: deliberate GIT_CONFIG_GLOBAL=/dev/null.
_REPO_LOCATING = frozenset(
    {
        "GIT_DIR",
        "GIT_WORK_TREE",
        "GIT_INDEX_FILE",
        "GIT_COMMON_DIR",
        "GIT_OBJECT_DIRECTORY",
        "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        "GIT_NAMESPACE",
        "GIT_PREFIX",
    }
)


def git_env() -> dict[str, str]:
    """The environment minus the variables that pick the repository.

    An exported ``GIT_DIR`` or ``GIT_WORK_TREE`` points git at some other
    repository whatever ``-C`` says. The split would then be computed against
    that repository's index, and a test that commits would commit into it.
    """
    return {k: v for k, v in os.environ.items() if k not in _REPO_LOCATING}


def _git(*args: str) -> bytes:
    return subprocess.run(
        ["git", "-C", str(ROOT), *args], capture_output=True, check=True, env=git_env()
    ).stdout


def _git_tracked() -> frozenset[str] | None:
    """Every tracked ``.net`` path under ROOTS, relative to ROOT, or None.

    None when git is missing, or when the repository around ROOT does not track
    ROOT's own ``pyproject.toml``. The second case is a tree with no ``.git`` of
    its own that sits inside some unrelated repository, such as an export
    unpacked under a home directory kept in git. That repository tracks none of
    these files, and calling all of them local would empty TRACKED rather than
    fall back.

    The anchor is the tracked ``pyproject.toml``, not "ROOT is the top of the
    work tree", because upstream development keeps bngsim as a ``bngsim/``
    subdirectory of a monorepo (``git subtree split -P bngsim``, per
    .pre-commit-config.yaml). There ROOT is below the top, and ``ls-files`` run
    from ROOT still reports paths relative to ROOT.
    """
    try:
        _git("ls-files", "--error-unmatch", "--", "pyproject.toml")
        out = _git("ls-files", "-z", "--", *ROOTS)
    except (OSError, subprocess.CalledProcessError):
        return None
    # fsdecode, not utf-8: a filename that is not valid UTF-8 (possible on
    # Linux) would otherwise raise here, at collection, in all four modules.
    return frozenset(name for name in map(os.fsdecode, out.split(b"\0")) if name.endswith(".net"))


def _on_disk() -> list[Path]:
    return sorted(
        p
        for root in ROOTS
        for p in (ROOT / root).rglob("*.net")
        if not _EXCLUDED_DIRS & set(p.relative_to(ROOT).parts[:-1])
    )


def _split() -> tuple[list[Path], list[Path], bool]:
    tracked = _git_tracked()
    if tracked is None:
        return _on_disk(), [], False
    # From git's own list, not by filtering the rglob, so the exclusions below,
    # which are about build and tool output, cannot drop a committed fixture.
    on_git = sorted(ROOT / rel for rel in tracked if (ROOT / rel).is_file())
    local = [p for p in _on_disk() if _rel(p) not in tracked]
    return on_git, local, True


TRACKED, LOCAL, GIT = _split()


def sweep_params() -> list:
    """``TRACKED`` then ``LOCAL``, as pytest params a sweep can parametrize over.

    A tracked case's id is its path below ROOT; a local case's id is that path
    prefixed ``local:``. With nothing to sweep, a single placeholder skips under
    a declared reason, because an empty parameter set skips under pytest's own
    wording, which the strict skip audit rejects.
    """
    params = [pytest.param(p, id=_rel(p)) for p in TRACKED]
    params += [pytest.param(p, id=f"local:{_rel(p)}") for p in LOCAL]
    return params or [pytest.param(None, marks=pytest.mark.skip(reason=ABSENT))]
